def wide(path):
    s=str(Path(path).absolute());return Path(s if os.name!='nt' or s.startswith('\\\\?\\') else '\\\\?\\'+s)
def sha(s):return hashlib.sha256(s.encode('utf8') if isinstance(s,str) else s).hexdigest()
def fixed_sources():
    root=Path(__file__).resolve().parent.parent/'upstream-slices/v032-catalog'
    raw=wide(root/'manifest.json').read_bytes()
    if sha(raw)!=MANIFEST_SHA256:raise ValueError('fixed v032 catalog manifest differs')
    manifest=json.loads(raw)
    if manifest['upstreamCommit']!=COMMIT or not manifest['partial']:raise ValueError('fixed catalog identity differs')
    result={}
    for row in manifest['sources']:
        name=row['path']
        if Path(name).name!=name or name in result:raise ValueError('unsafe fixed catalog source')
        body=wide(root/name).read_bytes()
        if len(body)!=row['bytes'] or sha(body)!=row['sha256'] or hashlib.sha1(b'blob '+str(len(body)).encode()+b'\0'+body).hexdigest()!=row['gitBlob']:
            raise ValueError('fixed catalog source bytes differ: '+name)
        result[name]=body.decode('utf8').replace('\r\n','\n')
    return manifest,result
def edits(text,rows):
    for r in rows:
        if text.count(r['before'])!=r['count']:raise ValueError('catalog source anchor differs: '+r['label'])
        text=text.replace(r['before'],r['after'],r['count'])
    return text
def apply(path,text):
    if path not in PATCHES:return text,None
    manifest,_=fixed_sources()
    output=edits(text,PATCHES[path])
    return output,dict(upstreamCommit=COMMIT,partial=True,path=path,beforeSha256LF=sha(text),afterSha256LF=sha(output),edits=PATCHES[path])
def apply_and_record(path,text,output):
    changed,proof=apply(path,text)
    if proof is not None:
        target=wide(Path(output)/(Path(path).name+'.v032-catalog-proof.json'));target.parent.mkdir(parents=True,exist_ok=True)
        target.write_bytes((json.dumps(proof,ensure_ascii=False,indent=2)+'\n').encode('utf8'))
    return changed
def generate(repo,output):
    manifest,source=fixed_sources()
    catalog=edits(source['VideoCatalogRepository.kt'],CATALOG_EDITS)
    outputs={'com/android/purebilibili/data/repository/DesktopOriginalVideoCatalogRepository.kt':catalog,
             'com/android/purebilibili/data/model/response/CreatorCardStats.kt':source['CreatorCardStats.kt'],
             'com/android/purebilibili/data/model/response/RelatedResponse.kt':source['RelatedResponse.kt']}
    for path,text in outputs.items():
        p=wide(Path(output)/path);p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(text.encode('utf8'))
    p=wide(Path(output)/'v032-catalog-source-proof.json')
    p.write_bytes((json.dumps(dict(upstreamCommit=COMMIT,partial=True,sourceManifest=MANIFEST_SHA256,outputs={p:sha(t) for p,t in outputs.items()},catalogEdits=CATALOG_EDITS),ensure_ascii=False,indent=2)+'\n').encode('utf8'))
if __name__=='__main__':
    import sys
    generate(Path(sys.argv[1]).resolve(),Path(sys.argv[2]).resolve())
